import 'package:flutter/widgets.dart' hide Animation, Image;
import 'package:fluvie/fluvie.dart';

import 'story_job.dart';

/// Compiles a validated job into the existing Fluvie renderer.
///
/// [transcriptPath] is the local SRT generated by [StoryJob.toSrt]. Audio is
/// muxed by the desktop runner with explicit padding/trimming to job duration.
Video buildStory(StoryJob job, {required String transcriptPath}) {
  rejectRemoteReference(transcriptPath);
  final zoom = job.template['zoom'];
  final alignment = job.template['captionAlignmentY'];
  if (alignment is! num) {
    throw const StoryJobException('Expected caption alignment.');
  }
  if (zoom is! num) throw const StoryJobException('Expected numeric zoom.');
  return Video(
    width: integer(job.profile, 'width'),
    height: integer(job.profile, 'height'),
    fps: integer(job.profile, 'fps'),
    poster: Time.ms(job.coverMs),
    captions: Captions.fromSrt(
      transcriptPath,
      style: CaptionStyle(
        textStyle: TextStyle(
          fontFamily: 'Roboto',
          fontSize: integer(job.template, 'captionFontSize').toDouble(),
          color: _color(string(job.template, 'captionColor')),
          fontWeight: FontWeight.w500,
        ),
        background: _color(string(job.template, 'captionBackground')),
        highlight: _color(string(job.template, 'captionColor')),
      ),
      position: CaptionPosition.custom(
        Alignment(0, alignment.toDouble()),
        safeArea: integer(job.template, 'captionInset').toDouble(),
      ),
    ),
    scenes: [
      for (final scene in job.scenes)
        Scene(
          duration: Time.frames(
            scene.durationMs * integer(job.profile, 'fps') ~/ 1000,
          ),
          background: Background.color(
            _color(string(job.template, 'background')),
          ),
          children: [
            SizedBox(
              width: integer(job.profile, 'width').toDouble(),
              height: integer(job.profile, 'height').toDouble(),
              child: Image.file(scene.imagePath, fit: BoxFit.cover),
            ).animate([Animation.kenBurns(zoom: zoom.toDouble())]),
          ],
        ),
    ],
  );
}

Color _color(String hex) {
  final digits = hex.substring(1);
  return Color(int.parse(digits.length == 6 ? 'FF$digits' : digits, radix: 16));
}
